static map<int,i64> lf;
static cpp_int ipow(int b,int e){ cpp_int r=1,x=b; while(e){ if(e&1)r*=x; e>>=1; if(e)x*=x; } return r; }
static void init_logs(){ for(int p:PR) lf[p]=(p==2 ? QLOG : (i64)boost::multiprecision::msb(ipow(p,(int)QLOG))); }
static map<int,int> factor_int(int x){ map<int,int> f; for(int p:PR) while(x%p==0){f[p]++;x/=p;} assert(x==1); return f; }
static i64 log_lo(int a){ if(a<=1)return 0; i64 s=0; for(auto [p,e]:factor_int(a)) s+=(i64)e*lf[p]; return s; }
static i64 log_hi(int a){ if(a<=1)return 0; i64 s=0; for(auto [p,e]:factor_int(a)) s+=(i64)e*(p==2?lf[p]:lf[p]+1); return s; }
static i64 t_lo(int a){ return a<=1?0:(i64)a*a*log_lo(a); }
static int C(int n,int k){ if(k<0||k>n)return 0; int r=1; for(int i=1;i<=k;i++) r=r*(n-k+i)/i; return r; }

static const array<pair<int,int>,21> PAIRS = [](){ array<pair<int,int>,21>a{}; int k=0; for(int i=0;i<7;i++)for(int j=i+1;j<7;j++)a[k++]={i,j}; return a; }();
static int edge_index(int a,int b){ if(a>b) swap(a,b); int k=0; for(int i=0;i<7;i++)for(int j=i+1;j<7;j++,k++) if(i==a&&j==b) return k; assert(false); return -1; }
static uint32_t permute_mask(uint32_t m,const array<int,7>&p){ uint32_t out=0; for(int k=0;k<21;k++) if((m>>k)&1u){ auto [i,j]=PAIRS[k]; int ii=p[i],jj=p[j]; out |= 1u<<edge_index(ii,jj); } return out; }

static vector<array<unsigned char,7>> all_profiles(){
  assert(REPS.size()==1044);
  vector<unsigned char> seen(1u<<21,0); array<int,7> p={0,1,2,3,4,5,6}; uint64_t covered=0;
  for(size_t ri=0;ri<REPS.size();ri++){
    vector<uint32_t> orb; orb.reserve(5040); p={0,1,2,3,4,5,6};
    do { orb.push_back(permute_mask(REPS[ri],p)); } while(next_permutation(p.begin(),p.end()));
    sort(orb.begin(),orb.end()); orb.erase(unique(orb.begin(),orb.end()),orb.end());
    for(uint32_t x:orb){ if(seen[x]){ cerr<<"graph orbit overlap\n"; exit(2); } seen[x]=1; }
    covered += orb.size();
  }
  if(covered!=(1u<<21)){ cerr<<"graph orbit coverage failure "<<covered<<"\n"; exit(3); }
  for(unsigned char x:seen) if(!x){ cerr<<"uncovered graph\n"; exit(4); }
  set<array<unsigned char,7>> profset;
  for(uint32_t g:REPS) for(int ell=0;ell<128;ell++){
    array<unsigned char,7>w{0,0,0,0,0,0,0};
    for(int s=1;s<128;s++){
      int q=__builtin_parity((unsigned)(ell&s));
      for(int k=0;k<21;k++) if((g>>k)&1u){ auto [i,j]=PAIRS[k]; if(((s>>i)&1) && ((s>>j)&1)) q^=1; }
      if(q) w[__builtin_popcount((unsigned)s)-1]++;
    }
    profset.insert(w);
  }
  if(profset.size()!=7172){ cerr<<"profile count failure "<<profset.size()<<"\n"; exit(5); }
  return vector<array<unsigned char,7>>(profset.begin(),profset.end());
}

static vector<int> mags(int m,int q){ set<int>a; int r=((m-4*q)%8+8)%8; for(int v=-m;v<=m;v+=2){ int rr=((v%8)+8)%8; if(rr==r)a.insert(abs(v)); } return vector<int>(a.begin(),a.end()); }

static i64 certify(const Cert& z,const vector<array<unsigned char,7>>& profiles){
  int m=z.m,B=z.B; i64 A=z.A,D=z.D; i64 base=0; array<i64,7> delta{};
  for(int d=1;d<=7;d++){
    i64 cq[2];
    for(int q=0;q<2;q++){
      cq[q]=LLONG_MAX/4;
      for(int a:mags(m,q)){ i64 val=t_lo(a) - (A + D*d)*(i64)a*a; cq[q]=min(cq[q],val); }
    }
    base += (i64)C(7,d)*cq[0]; delta[d-1]=cq[1]-cq[0];
  }
  i64 minprof=LLONG_MAX/4; array<unsigned char,7> winner{};
  for(auto &w:profiles){ i64 s=0; for(int d=0;d<7;d++) s+=(i64)w[d]*delta[d]; if(s<minprof){minprof=s;winner=w;} }
  i64 Q=(i64)m*(128-m), W=(i64)64*B; i64 T=A*Q + D*W + base + minprof; int a0=64-m;
  i64 L=24576LL*(B-7)*QLOG + 7LL*(t_lo(a0)+T) - 3969LL*B*log_hi(63);
  cout<<"CELL m="<<m<<" B="<<B<<" A="<<A<<" D="<<D<<" T_lower_num="<<T<<" L_lower_num="<<L<<" winner_profile=";
  for(int d=0;d<7;d++) cout<<(d?",":"")<<(int)winner[d]; cout<<"\n";
  if(L<=0){ cerr<<"nonpositive certificate for "<<m<<","<<B<<"\n"; exit(6); }
  return L;
}

int main(){
  init_logs(); auto profiles=all_profiles();
  cout<<"P03_C7_QUADRATIC_PROFILE_DUAL_EXACT\n";
  cout<<"graph_representatives="<<REPS.size()<<" graph_labeled_coverage="<<(1u<<21)<<" quadratic_degree_profiles="<<profiles.size()<<"\n";
  i64 mn=LLONG_MAX; for(auto &z:CERTS) mn=min(mn,certify(z,profiles));
  cout<<"new_certified_cells="<<CERTS.size()<<" min_L_lower_num="<<mn<<"\n";
  cout<<"P03-C7-QUADRATIC-PROFILE-DUAL-CERTIFICATE=PASS\n";
  return 0;
}
